// ╔══════════════════════════════════════════════════════════════════╗
// ║  PRIVACY GUARDRAIL – LOCAL KEYWORD EXTRACTOR                    ║
// ║  This node runs entirely inside n8n.                            ║
// ║  Raw email bodies and personal data are NEVER forwarded         ║
// ║  to any external LLM, API, or third-party service.              ║
// ║  Only matched keyword categories + extracted case references    ║
// ║  leave this node.                                               ║
// ╚══════════════════════════════════════════════════════════════════╝

const KEYWORDS = {
  emergency: [
    'ex-parte','deadline','urgent','response due','motion to compel',
    'asap','immediately','time-sensitive','due today','response needed',
    'please respond','dvro','rfo','request for order','electronic service'
  ],
  filing_service: [
    'dvro','restraining order','declaration','meet and confer','judgement',
    'stipulation','settlement','mediation','rfo','request for order'
  ],
  discovery: [
    'discovery','interrogatories','request for production','demand for production',
    'responses','verified responses','meet and confer','motion to compel',
    'deficiency','objections','supplemental responses'
  ],
  action_request: [
    'please review','please confirm','please advise','please provide',
    'please complete','please send','attached for your review'
  ]
};

// Regex to extract a case/matter reference number from subject or snippet
// Adjust to your firm's numbering format (e.g. "Case 2024-FL-0042")
const CASE_REF_RE = /(?:Case|Matter|File|Ref|Docket)[\s#:.\-]*([A-Z0-9\-]{4,20})/i;

// PII patterns to STRIP before any further processing
const PII_PATTERNS = [
  /\b[A-Z][a-z]+ [A-Z][a-z]+\b/g,          // Full names (basic heuristic)
  /\b[\w.+-]+@[\w-]+\.[a-z]{2,}\b/gi,       // Email addresses
  /\b(?:\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}\b/g, // Phone numbers
  /\b\d{3}-\d{2}-\d{4}\b/g,                // SSN
  /\b\d{1,5}\s+[\w\s]+(?:St|Ave|Rd|Blvd|Dr|Ct|Ln|Way|Pl)\b/gi // Street addresses
];

function stripPII(text) {
  let clean = text;
  for (const re of PII_PATTERNS) clean = clean.replace(re, '[REDACTED]');
  return clean;
}

function extractKeywords(text) {
  const lower = text.toLowerCase();
  const matched = {};
  for (const [cat, kws] of Object.entries(KEYWORDS)) {
    const hits = kws.filter(kw => lower.includes(kw));
    if (hits.length) matched[cat] = hits;
  }
  return matched;
}

const results = [];

for (const item of $input.all()) {
  const msg = item.json;

  // ── Pull only the fields we need ──────────────────────────────────
  const subject  = msg.subject   || '';
  const snippet  = msg.snippet   || '';   // Gmail short preview (< 200 chars)
  const from     = msg.from      || '';
  const date     = msg.date      || msg.internalDate || '';
  const msgId    = msg.id        || '';
  const threadId = msg.threadId  || '';

  // ── Combine subject + snippet for matching (NOT the full body) ────
  // Snippet is safe: it's already truncated by Gmail and contains no
  // more context than a push-notification preview.
  const searchText = `${subject} ${snippet}`;

  // ── Extract case reference BEFORE stripping PII ───────────────────
  const caseRefMatch = CASE_REF_RE.exec(searchText);
  const caseRef = caseRefMatch ? caseRefMatch[1].trim() : null;

  // ── Match keywords ────────────────────────────────────────────────
  const matched = extractKeywords(searchText);
  if (Object.keys(matched).length === 0) continue; // skip unrelated emails

  // ── Strip PII from what we forward ───────────────────────────────
  const safeSubject = stripPII(subject);
  const senderDomain = from.includes('@') ? '@' + from.split('@')[1].replace(/>.*/, '').trim() : '[unknown]';

  results.push({
    json: {
      // ── Safe metadata only ──
      emailId:      msgId,
      threadId:     threadId,
      receivedAt:   date,
      senderDomain: senderDomain,          // domain only, no name/address
      safeSubject:  safeSubject,           // PII-stripped subject
      // ── Extracted intelligence ──
      caseRef:        caseRef,             // e.g. "2024-FL-0042" or null
      matchedCategories: Object.keys(matched),
      matchedKeywords:   matched,
      isUrgent:       !!matched.emergency
    }
  });
}

return results;

// Build a unified notification payload from myCase staff data.
// Loads routing config to determine Slack/Telegram targets per role.

const ROUTING = {
  'Lead Attorney': { notify_via: ['slack', 'telegram'] },
  'Paralegal':     { notify_via: ['slack'] }
};

const staffList = $input.first().json.case_team_memberships || [];

// Find lead attorney and paralegal
const attorney   = staffList.find(m => m.role === 'Lead Attorney');
const paralegal  = staffList.find(m => m.role === 'Paralegal');

// Pull the keyword/case data from a few nodes back
const kwData = $('Privacy Filter & Keyword Extractor').first().json;
const caseData = $('myCase – Search Cases').first().json.cases?.[0] || {};

const recipients = [];
for (const member of [attorney, paralegal].filter(Boolean)) {
  const routing = ROUTING[member.role] || { notify_via: ['slack'] };
  recipients.push({
    name:         member.user?.name || member.role,
    role:         member.role,
    notify_via:   routing.notify_via,
    slack_user_id:    member.user?.slack_user_id    || null,
    telegram_chat_id: member.user?.telegram_chat_id || null
  });
}

const categories = kwData.matchedCategories.join(', ');
const urgencyTag = kwData.isUrgent ? '🚨 URGENT – ' : '';
const caseLabel  = caseData.display_number || kwData.caseRef || 'Unknown case';

const message = [
  `${urgencyTag}New email may relate to *${caseLabel}*`,
  `Category: ${categories}`,
  `Received: ${kwData.receivedAt}`,
  `Sender domain: ${kwData.senderDomain}`,
  `Subject (PII-stripped): ${kwData.safeSubject}`
].join('\n');

return recipients.map(r => ({
  json: { ...r, message, caseLabel, isUrgent: kwData.isUrgent }
}));

// No case found in myCase — build a fallback notification to the default channel.
const kwData = $('Privacy Filter & Keyword Extractor').first().json;
const categories = kwData.matchedCategories.join(', ');
const urgencyTag = kwData.isUrgent ? '🚨 URGENT – ' : '';

const message = [
  `${urgencyTag}Email matched keywords but *no matching case found* in myCase.`,
  `Category: ${categories}`,
  `Case ref in email: ${kwData.caseRef || 'None detected'}`,
  `Sender domain: ${kwData.senderDomain}`,
  `Subject (PII-stripped): ${kwData.safeSubject}`,
  `Please review and assign manually.`
].join('\n');

return [{
  json: {
    notify_via: ['slack'],
    slack_user_id: null,
    slack_channel_fallback: true,
    message,
    isUrgent: kwData.isUrgent
  }
}];
